def is_register_defined( _cs, reg_name ):
    try:
        return (_cs.Cfg.REGISTERS[ reg_name ] is not None)
    except KeyError:
        if logger().VERBOSE: logger().warn( "'%s' register definition not found in XML config" % reg_name)
        return False
